/**
 * Cross-check against the Python reference (`rating/glicko_sim.py`).
 *
 * The fixtures are generated by `rating/export_fixtures.py`: a seeded random history with
 * single battles, group battles, competition placements, all weight levels, inactivity,
 * initial estimates and a merged format. The specification allows ±1 point; since both
 * implementations use the same formulas we require a much tighter match.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  DEFAULT_RULESET_PARAMS,
  type Estimate,
  type FormatInfo,
  type RatingEvent,
  type RatingHistoryEntry,
  type RatingState,
  type RuleSetParams,
  replay,
} from '../src';

interface Fixture {
  params: Partial<RuleSetParams> & { weights: Record<string, number> };
  formats: FormatInfo[];
  events: RatingEvent[];
  estimates: Estimate[];
  expected: { states: RatingState[]; history: RatingHistoryEntry[] | null };
}

const TOLERANCE = 1e-6;

function load(name: string): Fixture {
  return JSON.parse(
    readFileSync(new URL(`./fixtures/${name}`, import.meta.url), 'utf8'),
  ) as Fixture;
}

function expectClose(actual: number, expected: number, label: string): void {
  if (Math.abs(actual - expected) > TOLERANCE) {
    expect.fail(`${label}: expected ${expected}, got ${actual}`);
  }
}

describe.each(['winner', 'both', 'none'])('reference replay with CLAMP=%s', (clamp) => {
  const fixture = load(`reference-clamp-${clamp}.json`);
  const params = { ...DEFAULT_RULESET_PARAMS, ...fixture.params } as RuleSetParams;
  // Shuffle the input order: the engine must sort by timestamp and id itself.
  const shuffled = [...fixture.events].reverse();
  const result = replay({
    events: shuffled,
    estimates: fixture.estimates,
    formats: fixture.formats,
    rulesets: { 1: params },
  });

  it('produces the same final states', () => {
    const actual = new Map(result.states.map((s) => [`${s.formatId}/${s.personId}`, s]));
    expect(actual.size).toBe(fixture.expected.states.length);
    for (const want of fixture.expected.states) {
      const key = `${want.formatId}/${want.personId}`;
      const got = actual.get(key);
      if (!got) return expect.fail(`missing state ${key}`);
      expectClose(got.r, want.r, `${key} r`);
      expectClose(got.rd, want.rd, `${key} rd`);
      expectClose(got.sigma, want.sigma, `${key} sigma`);
      expect(got.lastEventAt).toBe(want.lastEventAt);
      expect(got.nBattles).toBe(want.nBattles);
    }
  });

  it.runIf(fixture.expected.history !== null)('produces the same history, event by event', () => {
    const expected = fixture.expected.history ?? [];
    const key = (h: RatingHistoryEntry) => `${h.eventId}/${h.personId}`;
    const actual = new Map(result.history.map((h) => [key(h), h]));
    expect(result.history).toHaveLength(expected.length);
    for (const want of expected) {
      const got = actual.get(key(want));
      if (!got) return expect.fail(`missing history entry ${key(want)}`);
      expect(got.formatId).toBe(want.formatId);
      for (const field of [
        'rBefore',
        'rdBefore',
        'sigmaBefore',
        'rAfter',
        'rdAfter',
        'sigmaAfter',
      ] as const) {
        expectClose(got[field], want[field], `${key(want)} ${field}`);
      }
    }
  });
});
